fn get_word_bank(cat: Category) -> WordBank {
  let mut bank = WordBank{ category: cat, words: Vec[Str].new(), hints: Vec[Str].new() };
  if cat == Category.Animals {
    bank.words.push("ELEPHANT"); bank.words.push("GIRAFFE"); bank.words.push("PENGUIN");
    bank.words.push("DOLPHIN"); bank.words.push("CHEETAH");
    bank.hints.push("Largest land animal"); bank.hints.push("Tallest animal");
    bank.hints.push("Flightless bird"); bank.hints.push("Smart sea mammal");
    bank.hints.push("Fastest land animal");
  };
  bank
}
```

