### Hint System

```xiom
fn use_hint(game: &mut HangmanGame) -> Str {
  if game.hints_used >= 2 { return "No more hints!"; };
  if game.hint.len() > 0 {
    game.hints_used += 1;
    game.score -= 50;
    return game.hint.clone();
  };
  "No hint available."
}
```

### Round Scoring

```xiom
fn calculate_round_score(lives_remaining: Int, hints_used: Int, word_len: Int) -> Int {
  let base = lives_remaining * word_len * 10;
  let hint_penalty = hints_used * 50;
  let score = base - hint_penalty;
  if score < 0 { return 0; };
  score
}
```

