type HangmanDeluxe {
  word: Str;
  display: Str;
  lives: Int;
  score: Int;
}

fn update_display(game: &mut HangmanDeluxe, letter: Char) -> Bool {
  let mut hit = false;
  let mut new_display = "";
  let mut i = 0;
  while i < game.word.len() {
    if game.word.get(i).unwrap() == letter {
      new_display = string.str_concat(new_display, string.from_char(letter));
      hit = true;
    } else {
      new_display = string.str_concat(new_display, string.from_char(game.display.get(i).unwrap()));
    };
    i += 1;
  };
  game.display = new_display;
  if !hit { game.lives -= 1; };
  hit
}

fn is_word_complete(game: &HangmanDeluxe) -> Bool {
  let mut i = 0;
  while i < game.display.len() {
    if game.display.get(i).unwrap() == '_' { return false; };
    i += 1;
  };
  true
}

fn main() -> Int {
  let mut game = HangmanDeluxe{ word: "PYTHON", display: "______", lives: 6, score: 0 };
  update_display(&mut game, 'P');
  update_display(&mut game, 'Y');
  update_display(&mut game, 'X');
  io.println(game.display);
  io.println(game.lives);
  return 0;
}
